def runde_ungerade_zahlen_auf(liste):
    """Ersetzt jede ungerade Zahl in liste durch die naechstgroessere gerade Zahl."""
    for i in range(len(liste)):
        if liste[i] % 2 != 0:
            liste[i] = liste[i] + 1

testliste = [1, 2, 3, 4, 5]
print(runde_ungerade_zahlen_auf(testliste))  # None -> die Funktion gibt nichts zurück
print(testliste)                             # [2, 2, 4, 4, 6] -> die Liste wurde mutiert

def haeufigkeiten(wuerfe):
    """
    Zaehlt, wie oft jeder Wert in wuerfe vorkommt.
    Eingabe: wuerfe - Liste von Werten
    Ausgabe: Dictionary {wert: anzahl}
    """
    zaehler = {}
    for wurf in wuerfe:
        if wurf in zaehler:
            zaehler[wurf] = zaehler[wurf] + 1
        else:
            zaehler[wurf] = 1
    return zaehler

