anfangs_state = {'punkte1': 0, 'punkte2': 0, 'preiskarten': (1, 2, 3)}

def spielrunde(state, karte1, karte2):
    preiskarte = state['preiskarten'][-1]
    neuer_state = {'punkte1': state['punkte1'],
                   'punkte2': state['punkte2'],
                   'preiskarten': state['preiskarten'][:-1]}
    if karte1 > karte2:
        neuer_state['punkte1'] = state['punkte1'] + preiskarte
    elif karte2 > karte1:
        neuer_state['punkte2'] = state['punkte2'] + preiskarte
    return neuer_state

states = (anfangs_state,)
states += (spielrunde(states[-1], 5, 2),)
print(states[-1])   # {'punkte1': 3, 'punkte2': 0, 'preiskarten': (1, 2)}
